CREATE TABLE "sm_supplier_profiles" ("id" TEXT NOT NULL,"company_id" TEXT NOT NULL,"party_id" TEXT NOT NULL,"supplier_code" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"approval_status" TEXT NOT NULL DEFAULT 'PENDING',"default_currency" TEXT NOT NULL,"credit_days" INTEGER NOT NULL DEFAULT 0,"contact_person" TEXT,"notes" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "sm_supplier_profiles_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "sm_supplier_profiles_company_id_id_key" ON "sm_supplier_profiles"("company_id","id");
CREATE UNIQUE INDEX "sm_supplier_profiles_company_id_party_id_key" ON "sm_supplier_profiles"("company_id","party_id");
CREATE UNIQUE INDEX "sm_supplier_profiles_company_id_supplier_code_key" ON "sm_supplier_profiles"("company_id","supplier_code");
CREATE INDEX "sm_supplier_profiles_company_id_status_approval_status_idx" ON "sm_supplier_profiles"("company_id","status","approval_status");
CREATE TABLE "sm_supplier_categories" ("id" TEXT NOT NULL,"company_id" TEXT NOT NULL,"code" TEXT NOT NULL,"label" TEXT NOT NULL,CONSTRAINT "sm_supplier_categories_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "sm_supplier_categories_company_id_code_key" ON "sm_supplier_categories"("company_id","code");
CREATE TABLE "sm_supplier_category_links" ("company_id" TEXT NOT NULL,"supplier_id" TEXT NOT NULL,"category_code" TEXT NOT NULL,CONSTRAINT "sm_supplier_category_links_pkey" PRIMARY KEY ("company_id","supplier_id","category_code"));
CREATE INDEX "sm_supplier_category_links_company_id_category_code_idx" ON "sm_supplier_category_links"("company_id","category_code");
CREATE TABLE "sm_supplier_approvals" ("id" TEXT NOT NULL,"company_id" TEXT NOT NULL,"supplier_id" TEXT NOT NULL,"decision" TEXT NOT NULL,"source" TEXT NOT NULL,"actor_id" TEXT NOT NULL,"reason" TEXT,"decided_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "sm_supplier_approvals_pkey" PRIMARY KEY ("id"));
CREATE INDEX "sm_supplier_approvals_company_id_supplier_id_decided_at_idx" ON "sm_supplier_approvals"("company_id","supplier_id","decided_at");
CREATE TABLE "sm_supplier_bank_accounts" ("id" TEXT NOT NULL,"company_id" TEXT NOT NULL,"supplier_id" TEXT NOT NULL,"bank_name" TEXT NOT NULL,"account_number" TEXT NOT NULL,"iban" TEXT,"currency" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"is_default" BOOLEAN NOT NULL DEFAULT false,"created_by" TEXT NOT NULL,"updated_by" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "sm_supplier_bank_accounts_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "sm_supplier_bank_accounts_company_id_id_key" ON "sm_supplier_bank_accounts"("company_id","id");
CREATE INDEX "sm_supplier_bank_accounts_company_id_supplier_id_active_idx" ON "sm_supplier_bank_accounts"("company_id","supplier_id","active");
CREATE UNIQUE INDEX "sm_supplier_bank_accounts_one_default" ON "sm_supplier_bank_accounts"("company_id","supplier_id") WHERE "is_default" = true;
CREATE TABLE "sm_supplier_legacy_refs" ("company_id" TEXT NOT NULL,"source" TEXT NOT NULL,"legacy_supplier_id" TEXT NOT NULL,"supplier_id" TEXT NOT NULL,"party_id" TEXT NOT NULL,"fingerprint" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "sm_supplier_legacy_refs_pkey" PRIMARY KEY ("company_id","source","legacy_supplier_id"));
CREATE INDEX "sm_supplier_legacy_refs_company_id_supplier_id_idx" ON "sm_supplier_legacy_refs"("company_id","supplier_id");
CREATE TABLE "sm_supplier_history" ("id" TEXT NOT NULL,"company_id" TEXT NOT NULL,"supplier_id" TEXT NOT NULL,"action" TEXT NOT NULL,"actor_id" TEXT NOT NULL,"occurred_at" TIMESTAMP(3) NOT NULL,"metadata" JSONB NOT NULL,CONSTRAINT "sm_supplier_history_pkey" PRIMARY KEY ("id"));
CREATE INDEX "sm_supplier_history_company_id_supplier_id_occurred_at_idx" ON "sm_supplier_history"("company_id","supplier_id","occurred_at");
ALTER TABLE "sm_supplier_category_links" ADD CONSTRAINT "sm_supplier_category_links_supplier_fkey" FOREIGN KEY ("company_id","supplier_id") REFERENCES "sm_supplier_profiles"("company_id","id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "sm_supplier_category_links" ADD CONSTRAINT "sm_supplier_category_links_category_fkey" FOREIGN KEY ("company_id","category_code") REFERENCES "sm_supplier_categories"("company_id","code") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "sm_supplier_approvals" ADD CONSTRAINT "sm_supplier_approvals_supplier_fkey" FOREIGN KEY ("company_id","supplier_id") REFERENCES "sm_supplier_profiles"("company_id","id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "sm_supplier_bank_accounts" ADD CONSTRAINT "sm_supplier_bank_accounts_supplier_fkey" FOREIGN KEY ("company_id","supplier_id") REFERENCES "sm_supplier_profiles"("company_id","id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "sm_supplier_legacy_refs" ADD CONSTRAINT "sm_supplier_legacy_refs_supplier_fkey" FOREIGN KEY ("company_id","supplier_id") REFERENCES "sm_supplier_profiles"("company_id","id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "sm_supplier_history" ADD CONSTRAINT "sm_supplier_history_supplier_fkey" FOREIGN KEY ("company_id","supplier_id") REFERENCES "sm_supplier_profiles"("company_id","id") ON DELETE RESTRICT ON UPDATE CASCADE;
